/**
 * Read-aloud playback for Eno messages.
 *
 * Audio is generated by the server-side ElevenLabs proxy at `/api/tts` and
 * played through the Web Audio API. The AudioContext is created/resumed
 * synchronously in the click handler (before the network request) so iOS and
 * Safari allow playback once the audio bytes arrive.
 */

type AudioContextConstructor = typeof AudioContext;

function contextConstructor(): AudioContextConstructor | undefined {
  if (typeof window === 'undefined') return undefined;
  const candidate = window as unknown as {
    AudioContext?: AudioContextConstructor;
    webkitAudioContext?: AudioContextConstructor;
  };
  return candidate.AudioContext ?? candidate.webkitAudioContext;
}

let context: AudioContext | null = null;
let currentSource: AudioBufferSourceNode | null = null;
let currentController: AbortController | null = null;
let generation = 0;

function ensureContext(): AudioContext | null {
  try {
    context ??= new (contextConstructor() as AudioContextConstructor)();
    if (context.state === 'suspended') void context.resume();
    return context;
  } catch {
    return null;
  }
}

export function supportsReadAloud(): boolean {
  return typeof window !== 'undefined' && typeof window.fetch === 'function' && Boolean(contextConstructor());
}

/** Abort any in-flight request and stop the active playback. */
export function stopReadAloud(): void {
  generation += 1;
  currentController?.abort();
  currentController = null;
  const source = currentSource;
  currentSource = null;
  if (source) {
    try {
      source.stop();
    } catch {
      // The source may already have finished.
    }
  }
}

export async function readAloud(
  text: string,
  reportError: (notice: string) => void,
  onEnd?: () => void
): Promise<void> {
  const trimmed = text.trim();
  if (!trimmed) return;

  // Unlock audio inside the click call, before the first await.
  const audioContext = ensureContext();
  stopReadAloud();
  if (!audioContext) {
    reportError('Voice isn’t available right now. You can keep chatting here.');
    return;
  }

  const myGeneration = generation;
  const controller = new AbortController();
  currentController = controller;

  try {
    const response = await fetch('/api/tts', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ text: trimmed }),
      signal: controller.signal
    });
    if (myGeneration !== generation) return;

    if (!response.ok) {
      if (response.status === 413) reportError('That message is too long to read aloud.');
      else if (response.status === 429) reportError('Voice is busy right now. Try again in a moment.');
      else reportError('Voice couldn’t start. You can keep chatting here.');
      return;
    }

    let bytes: ArrayBuffer;
    try {
      bytes = await response.arrayBuffer();
    } catch {
      if (myGeneration !== generation) return;
      reportError('Voice couldn’t start. You can keep chatting here.');
      return;
    }
    if (myGeneration !== generation) return;

    let buffer: AudioBuffer;
    try {
      buffer = await audioContext.decodeAudioData(bytes);
    } catch {
      if (myGeneration !== generation) return;
      reportError('Voice isn’t available right now. You can keep chatting here.');
      return;
    }
    if (myGeneration !== generation) return;

    if (audioContext.state === 'suspended') void audioContext.resume();
    const source = audioContext.createBufferSource();
    source.buffer = buffer;
    source.connect(audioContext.destination);
    currentSource = source;
    source.onended = () => {
      if (currentSource !== source) return;
      currentSource = null;
      if (myGeneration === generation) onEnd?.();
    };
    source.start();
  } catch {
    if (controller.signal.aborted || myGeneration !== generation) return;
    reportError('Voice couldn’t start. You can keep chatting here.');
  }
}
